import{_ as t,o as a,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"2. Installing a C Compiler (gcc, clang, tinycc)","description":"The Little Book of C — 2. Installing a C Compiler (gcc, clang, tinycc)","frontmatter":{"title":"2. Installing a C Compiler (gcc, clang, tinycc)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 2. Installing a C Compiler (gcc, clang, tinycc)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":2,"sidebarWeight":2,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc)","alternateZh":"/posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc)"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc).md","filePath":"posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc).md","lastUpdated":1790163617000}'),s={name:"posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc).md"};function o(l,e,c,r,p,d){return a(),n("div",null,[...e[0]||(e[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc))</p><p>Before you can write and run C programs, you need a compiler. A compiler is a tool that translates your human-readable code into the machine instructions that your CPU understands. In C, this process is explicit, you see it, control it, and learn from it.</p><p>There are many compilers available, but three are most common:</p><ul><li>GCC (GNU Compiler Collection)**, The standard compiler on Linux and macOS, known for reliability and wide support.</li><li>Clang, A modern compiler built for speed, cleaner diagnostics, and integration with tools like LLVM.</li><li>TinyCC (tcc), A super-lightweight compiler that’s perfect for learning and quick testing.</li></ul><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>You can check if you already have a compiler installed by running one of these commands in your terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc --version</span></span>
<span class="line"><span>clang --version</span></span>
<span class="line"><span>tcc --version</span></span></code></pre></div><p>If you see a version number, you’re ready. If not, you’ll need to install one.</p><h4 id="installing-on-different-systems" tabindex="-1">Installing on Different Systems <a class="header-anchor" href="#installing-on-different-systems" aria-label="Permalink to &quot;Installing on Different Systems&quot;">​</a></h4><p>Linux (Debian/Ubuntu):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install build-essential</span></span></code></pre></div><p>This installs GCC along with other useful tools like<code>make</code>.</p><p>macOS (with Xcode Command Line Tools):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xcode-select --install</span></span></code></pre></div><p>This installs Clang and the developer toolchain.</p><p>Windows (via Mingw-w64):</p><ol><li>Go to Mingw-w64.</li><li>Download and install it.</li><li>Add the compiler’s<code>bin</code> folder to your system PATH.</li><li>Open<code>cmd</code> or PowerShell and run<code>gcc --version</code> to confirm.</li></ol><p>Or, if you prefer an all-in-one environment, install WSL (Windows Subsystem for Linux) and use the Linux commands above.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Installing a compiler is your first step toward understanding how programs become executables. In C, there’s no hidden build system or automatic runtime, everything that happens between writing code and running it is visible. That clarity is part of what makes C such a powerful learning tool.</p><p>When you install your compiler, you’re also installing the ability to explore how software really works.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Open your terminal or command prompt.</p><p>Type<code>gcc --version</code> or<code>clang --version</code> to confirm installation.</p><p>Create a simple file named<code>test.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(void) { return 0; }</span></span></code></pre></div><p>Compile it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc test.c -o test</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./test</span></span></code></pre></div><p>If it runs with no output, that’s perfect, your compiler is ready. You’ve just built your very first executable program from source code.</p>`,31)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
